/**
 * Built-in ingredient & additive database used by the label scanner.
 *
 * risk (evidence-based, ours):
 *   0 = no known concern at normal use levels
 *   1 = limited concern (allergen, laxative effect, debated, contamination potential, minor)
 *   2 = moderate concern (debated safety, restricted somewhere, IARC 2B with an active
 *       regulatory question, hormone activity, high added sugar, etc.)
 *   3 = high concern (banned in a major jurisdiction, IARC Group 1 / 2A exposure route,
 *       or strong evidence of harm at realistic intakes)
 *
 * yuka (optional): the tier the Yuka app currently gives the ingredient, where we could
 *   verify it from Yuka's own published change logs or test reports. Shown as a separate
 *   signal; Yuka is precautionary and a red there is NOT a cancer classification.
 *
 * domain: where the entry applies. 'food' | 'cosmetic' | 'household' | 'any' (default).
 *   A food-only entry (sugar, red meat) is ignored when a cosmetics label is scanned.
 *
 * score (0–100) and carc come from src/data/scores.ts (generated by scripts/build-scores.py):
 *   0 = any cancer link ("classified" or the weaker "linked"); 1–100 = everything else.
 *   The 0–3 `risk` field below is the older coarse rating, kept as documentation and fallback.
 *
 * `evidence` names the public classification the rating leans on (IARC group, EU/US
 * regulatory action, EFSA/FDA/SCCS position) so every flag can be checked.
 * Last reviewed November 2026. Informational, not medical advice.
 */
import { SCORES, type CarcLevel, type ScoreSpec } from './scores';

export type Domain = 'food' | 'cosmetic' | 'household' | 'any';
export type Domains = Domain | Domain[];
export interface Carc { level: CarcLevel; why: string }
export type Yuka = 'red' | 'orange' | 'yellow' | 'green';

export interface Additive {
  code?: string;          // E-number if any (E102). INS numbers share the digits.
  name: string;
  aliases: string[];      // lower-case substrings that identify it on a label
  cat: string;            // colour, preservative, sweetener, …
  risk: 0 | 1 | 2 | 3;
  why: string;            // plain-English one-liner
  evidence?: string;
  cas?: string;
  yuka?: Yuka;
  domain?: Domains;
  score: number;          // 0–100, see scores.ts
  carc?: Carc;            // present when score is 0
  topical?: { score: number; carc?: Carc }; // on-skin score, only where the concern depends on the route
}

