const FALLBACK = [88, 60, 35, 10];
const unpack = (sp: ScoreSpec): { score: number; carc?: Carc } =>
  sp.length === 3 ? { score: 0, carc: { level: sp[1], why: sp[2] } } : { score: sp[0] };
export const ADDITIVES: Additive[] = RAW.map((a) => {
  const sc = SCORES[a.name];
  if (!sc) return { ...a, score: FALLBACK[a.risk] };
  return { ...a, ...unpack(sc[0]), ...(sc[1] ? { topical: unpack(sc[1]) } : {}) };
});

/** Fast lookup by E-number digits, e.g. "171" → titanium dioxide (food entry wins). */
export const BY_CODE: Record<string, Additive> = {};
for (const a of ADDITIVES) {
  for (const al of a.aliases) {
    const m = al.match(/^(?:e|ins )?(\d{3,4}[a-z]?)$/);
    if (m && !BY_CODE[m[1]]) BY_CODE[m[1]] = a;
  }
  if (a.code) {
    const k = a.code.slice(1).toLowerCase();
    if (!BY_CODE[k]) BY_CODE[k] = a;
  }
}

export const RISK_LABEL: Record<number, string> = { 0: 'Low concern', 1: 'Limited concern', 2: 'Moderate concern', 3: 'High concern' };
export const CARC_LABEL: Record<CarcLevel, string> = { classified: 'Classified carcinogen', linked: 'Cancer link (weaker evidence)' };
export const YUKA_LABEL: Record<Yuka, string> = { red: 'Yuka: high risk', orange: 'Yuka: moderate risk', yellow: 'Yuka: low risk', green: 'Yuka: risk-free' };
